import{_ as o,o as t,c as a,a3 as n}from"./chunks/framework.DH50UWNB.js";const u=JSON.parse('{"title":"Sign-in providers","description":"Turn on sign-in with GitHub, Google, Microsoft or an OpenID Connect provider such as Okta or Keycloak, and how Wake matches accounts.","frontmatter":{"description":"Turn on sign-in with GitHub, Google, Microsoft or an OpenID Connect provider such as Okta or Keycloak, and how Wake matches accounts."},"headers":[],"relativePath":"run/sign-in-providers.md","filePath":"run/sign-in-providers.md","lastUpdated":1794486787000}'),i={name:"run/sign-in-providers.md"};function r(s,e,c,d,l,h){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="sign-in-providers" tabindex="-1">Sign-in providers <a class="header-anchor" href="#sign-in-providers" aria-label="Permalink to &quot;Sign-in providers&quot;">​</a></h1><p>Besides email and password, people can sign in with GitHub, Google, Microsoft and one OpenID Connect provider (Okta, Keycloak, Auth0, Authentik and others). Each provider is off until you set all of its variables; a partial group stops the server at start, naming the missing variables. The web app shows a button for each provider that is on, and never learns a client id, secret or issuer.</p><h2 id="turn-one-on" tabindex="-1">Turn one on <a class="header-anchor" href="#turn-one-on" aria-label="Permalink to &quot;Turn one on&quot;">​</a></h2><ol><li><p>Register Wake with the provider as a web application, with the callback URL <code>&lt;PUBLIC_URL&gt;/v1/auth/&lt;provider&gt;/callback</code>, where <code>&lt;PUBLIC_URL&gt;</code> is your Wake URL and <code>&lt;provider&gt;</code> is <code>github</code>, <code>google</code>, <code>microsoft</code> or <code>oidc</code>. For <code>https://wake.example.com</code>, Google&#39;s is <code>https://wake.example.com/v1/auth/google/callback</code>.</p></li><li><p>Add the provider&#39;s lines to the installation&#39;s <code>.env</code>, keeping its mode <code>0600</code>. A value with <code>$</code> or spaces goes in single quotes:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GOOGLE_CLIENT_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">...</span></span>
<span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GOOGLE_CLIENT_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">...</span></span></code></pre></div></li><li><p>Run <code>wake-server start</code>, which recreates the server with them. Upgrades keep <code>.env</code>.</p></li></ol><p>In local mode your Wake URL is on <code>localhost</code>, so a provider sends the browser back to the machine that runs Wake: provider sign-in works only in a browser on that machine. To sign in with a provider from other machines, <a href="/wake-dist/docs/run/install-options#install-on-a-domain">install on a domain</a>.</p><p>A server you run yourself takes the same variables in its environment; see <a href="/wake-dist/docs/reference/environment#sign-in-providers">Server environment</a>.</p><h2 id="how-accounts-are-matched" tabindex="-1">How accounts are matched <a class="header-anchor" href="#how-accounts-are-matched" aria-label="Permalink to &quot;How accounts are matched&quot;">​</a></h2><p>Wake identifies an account by the provider&#39;s own account id, never by its email. The first sign-in with a provider account creates a user with a personal workspace, and only when the provider reports the email as verified. An email that already belongs to a Wake user is never linked automatically: that person signs in the way they already do and links the provider from <strong>Account</strong> (<a href="/wake-dist/docs/use/account#sign-in-methods">Sign-in methods</a>).</p><p>Every provider&#39;s sign-in uses PKCE (S256): a code intercepted on its way back cannot be redeemed without the verifier the server keeps in the sign-in&#39;s HttpOnly cookie. It needs no setting.</p><p>Sign-in providers follow <a href="/wake-dist/docs/run/sign-up">who can sign up</a>: on a server open only to invitations, a new account through a provider needs an invitation too, and every new account counts against the free plan&#39;s people.</p><h2 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub&quot;">​</a></h2><ol><li>In GitHub, open <strong>Settings → Developer settings → OAuth Apps</strong> and choose <strong>New OAuth App</strong>.</li><li>Set <strong>Authorization callback URL</strong> to <code>&lt;PUBLIC_URL&gt;/v1/auth/github/callback</code>.</li><li>Generate a client secret, then set <code>GITHUB_CLIENT_ID</code> and <code>GITHUB_CLIENT_SECRET</code>.</li></ol><p>Wake asks for the <code>read:user</code> and <code>user:email</code> scopes and uses the account&#39;s primary email, only when GitHub reports it verified.</p><h2 id="google" tabindex="-1">Google <a class="header-anchor" href="#google" aria-label="Permalink to &quot;Google&quot;">​</a></h2><p>Google sign-in accepts Gmail and Google Workspace accounts.</p><ol><li>In the <a href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noreferrer">Google Cloud console</a>, configure the OAuth consent screen, then create an <strong>OAuth client ID</strong> of type <strong>Web application</strong>.</li><li>Add <code>&lt;PUBLIC_URL&gt;/v1/auth/google/callback</code> under <strong>Authorized redirect URIs</strong>.</li><li>Set <code>GOOGLE_CLIENT_ID</code> and <code>GOOGLE_CLIENT_SECRET</code> to the client&#39;s id and secret.</li></ol><p>Wake asks for the <code>openid</code>, <code>email</code> and <code>profile</code> scopes and trusts Google&#39;s <code>email_verified</code> claim.</p><h2 id="microsoft" tabindex="-1">Microsoft <a class="header-anchor" href="#microsoft" aria-label="Permalink to &quot;Microsoft&quot;">​</a></h2><p>Microsoft sign-in accepts work or school accounts (Microsoft Entra ID) from any organization and personal Microsoft accounts, through the multi-tenant issuer <code>https://login.microsoftonline.com/common/v2.0</code>.</p><ol><li>In the <a href="https://entra.microsoft.com" target="_blank" rel="noreferrer">Microsoft Entra admin center</a>, open <strong>App registrations</strong> and choose <strong>New registration</strong>.</li><li>Under <strong>Supported account types</strong>, choose <strong>Accounts in any organizational directory and personal Microsoft accounts</strong>.</li><li>Add a <strong>Web</strong> redirect URI <code>&lt;PUBLIC_URL&gt;/v1/auth/microsoft/callback</code>.</li><li>Under <strong>Certificates &amp; secrets</strong>, create a client secret.</li><li>Under <strong>Token configuration</strong>, choose <strong>Add optional claim</strong>, token type <strong>ID</strong>, and add <code>email</code> and <code>xms_edov</code>.</li><li>Set <code>MICROSOFT_CLIENT_ID</code> to the <strong>Application (client) ID</strong> and <code>MICROSOFT_CLIENT_SECRET</code> to the secret&#39;s value. The secret expires; create a new one before it does.</li></ol><p>A tenant administrator can set a work account&#39;s <code>email</code> claim to any address, so Wake counts it as verified only for personal accounts or when the <code>xms_edov</code> claim states that the domain owner verified it. Without the optional claim, a work account cannot create a Wake user (<code>provider_email_unverified</code>): that person signs up with a password or another provider and links Microsoft from <strong>Account</strong>.</p><h2 id="openid-connect" tabindex="-1">OpenID Connect <a class="header-anchor" href="#openid-connect" aria-label="Permalink to &quot;OpenID Connect&quot;">​</a></h2><p>One more provider that speaks OpenID Connect can sign people in, under a name you choose.</p><ol><li>In your identity provider, create a confidential web application (client) that uses the authorization code flow, with the redirect URI <code>&lt;PUBLIC_URL&gt;/v1/auth/oidc/callback</code> and the <code>openid</code>, <code>email</code> and <code>profile</code> scopes.</li><li>Set <code>OIDC_ISSUER</code> to its issuer URL, the one whose <code>/.well-known/openid-configuration</code> document Wake reads (for example <code>https://sso.example.com/realms/wake</code> for a Keycloak realm), and <code>OIDC_CLIENT_ID</code> and <code>OIDC_CLIENT_SECRET</code> to the client&#39;s credentials.</li><li>Set <code>OIDC_NAME</code> to the text of its button, for example <code>Acme SSO</code>: 1 to 40 characters.</li></ol><p><code>OIDC_ISSUER</code> must use <code>https</code> (<code>http</code> only on <code>localhost</code>), without a query or fragment. The provider must sign ID tokens with keys published at its <code>jwks_uri</code> and report verified emails with <code>email_verified</code>. Wake uses PKCE (<code>S256</code>) and a nonce, and checks the ID token&#39;s signature, issuer, audience, expiry and nonce.</p><h2 id="errors-people-can-meet" tabindex="-1">Errors people can meet <a class="header-anchor" href="#errors-people-can-meet" aria-label="Permalink to &quot;Errors people can meet&quot;">​</a></h2><p>When a provider sign-in fails, the browser goes back to the screen it started from, which says what happened; starting the sign-in again is safe. Each message and what to do about it are in <a href="/wake-dist/docs/reference/troubleshooting#sign-in-provider-errors">Troubleshooting</a>.</p>`,27)])])}const g=o(i,[["render",r]]);export{u as __pageData,g as default};
